#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

double minmaxGasDist(const int *stations, int n, int k) {
    double lo = 0.0;
    double hi = (double)stations[n - 1] - stations[0];

    for (int iter = 0; iter < 100; ++iter) {
        double mid = (lo + hi) / 2.0;
        long long needed = 0;
        for (int i = 0; i + 1 < n; ++i) {
            double gap = (double)stations[i + 1] - stations[i];
            needed += (long long)ceil(gap / mid) - 1;
            if (needed > k) break;
        }
        if (needed <= k) hi = mid;
        else lo = mid;
    }
    return hi;
}

